import React, { useState, useRef, useEffect } from 'react';
import { useStore } from '../../store/useStore';
import { generateVivaQuestions, gradeVivaAnswer, gradeVivaSession } from '../../utils/aiService';
import { apiPost, apiGet } from '../../utils/api';

export default function VivaRoom() {
  var store = useStore();
  var [phase,         setPhase]         = useState('setup');
  var [title,         setTitle]         = useState('');
  var [topic,         setTopic]         = useState('');
  var [savedViva,     setSavedViva]     = useState(null);
  var savedVivaRef = useRef(null);

  // Q&A state
  var [questions,     setQuestions]     = useState([]);
  var [currentQ,      setCurrentQ]      = useState(0);
  var [studentAnswer, setStudentAnswer] = useState('');
  var [examinerNotes, setExaminerNotes] = useState('');
  var [verdict,       setVerdict]       = useState(null);
  var [transcript,    setTranscript]    = useState([]);

  // Generation
  var [genTopic,      setGenTopic]      = useState('');
  var [genCount,      setGenCount]      = useState(5);
  var [loading,       setLoading]       = useState(false);

  // Invite
  var [showInvite,    setShowInvite]    = useState(false);
  var [inviteMode,    setInviteMode]    = useState('account'); // 'email' | 'account'
  var [inviteEmail,   setInviteEmail]   = useState('');
  var [students,      setStudents]      = useState([]);
  var [selectedStu,   setSelectedStu]   = useState([]);
  var [inviteMsg,     setInviteMsg]     = useState('');
  var [inviting,      setInviting]      = useState(false);

  // Student alerts (away / return / timeout)
  var [studentAlerts, setStudentAlerts] = useState([]);
  var [unreadAlerts,  setUnreadAlerts]  = useState(0);
  var [showAlerts,    setShowAlerts]    = useState(false);

  // Results
  var [results,       setResults]       = useState(null);

  // Camera
  var adminVid = useRef(null);
  var streamRef = useRef(null);

  // Poll for student-related notifications while in room
  var pollRef = useRef(null);

  // ── Create viva room ───────────────────────────────────────
  async function handleStartRoom() {
    if (!title.trim()) return;
    setLoading(true);
    try {
      var r = await apiPost('/viva', { title: title, topic: topic, questions: [] });
      var vivaData = { viva_id: r.viva_id, title: title, topic: topic };
      savedVivaRef.current = vivaData;
      setSavedViva(vivaData);
      setPhase('room');
      setTimeout(startMedia, 300);
      startAlertPolling();
    } catch (e) { alert(e.message); }
    setLoading(false);
  }

  // ── Camera ─────────────────────────────────────────────────
  function startMedia() {
    navigator.mediaDevices.getUserMedia({ video: true, audio: true })
      .then(function (stream) {
        streamRef.current = stream;
        var iv = setInterval(function () {
          if (adminVid.current) { adminVid.current.srcObject = stream; clearInterval(iv); }
        }, 200);
      })
      .catch(function () {});
  }
  function stopMedia() {
    if (streamRef.current) streamRef.current.getTracks().forEach(function (t) { t.stop(); });
    clearInterval(pollRef.current);
  }

  // ── Poll notifications for student alerts ──────────────────
  function startAlertPolling() {
    var lastSeen = Date.now();
    pollRef.current = setInterval(async function () {
      try {
        var notifs = await apiGet('/notifications');
        var fresh  = (notifs || []).filter(function (n) {
          var isRelevant =
            n.title && (
              n.title.includes('Left Viva') ||
              n.title.includes('Returned to Viva') ||
              n.title.includes('Removed — Viva') ||
              n.title.includes('Exam Submitted') ||
              n.title.includes('INTEGRITY VIOLATION')
            );
          var ts = n.created_at ? new Date(n.created_at).getTime() : 0;
          return isRelevant && ts > lastSeen;
        });
        if (fresh.length > 0) {
          lastSeen = Date.now();
          setStudentAlerts(function (prev) { return fresh.concat(prev).slice(0, 30); });
          setUnreadAlerts(function (prev) { return prev + fresh.length; });
        }
      } catch (e) {}
    }, 6000); // poll every 6 s
  }

  // ── Generate questions ─────────────────────────────────────
  async function handleGenerateQ() {
    if (!genTopic) return;
    setLoading(true);
    try {
      var qs = await generateVivaQuestions(genTopic, genCount);
      setQuestions(qs);
      setCurrentQ(0);
    } catch (e) { alert('Generation failed: ' + e.message); }
    setLoading(false);
  }

  // ── Grade one answer ───────────────────────────────────────
  async function handleCheckAnswer() {
    if (!studentAnswer || !questions[currentQ]) return;
    setLoading(true);
    try {
      var v = await gradeVivaAnswer(questions[currentQ].question, questions[currentQ].model_answer, studentAnswer);
      setVerdict(v);
    } catch (e) { alert(e.message); }
    setLoading(false);
  }

  // ── Save & next ────────────────────────────────────────────
  function handleSaveNext() {
    var entry = {
      question:      questions[currentQ].question,
      model_answer:  questions[currentQ].model_answer,
      student_answer: studentAnswer,
      notes:         examinerNotes,
      verdict:       verdict,
    };
    setTranscript(function (t) { return t.concat([entry]); });
    setStudentAnswer(''); setExaminerNotes(''); setVerdict(null);
    if (currentQ < questions.length - 1) setCurrentQ(function (q) { return q + 1; });
  }

  // ── End & grade full session ───────────────────────────────
  async function handleEndGrade() {
    stopMedia();
    setLoading(true);
    try {
      var tText = transcript.map(function (t, i) {
        return 'Q' + (i+1) + ': ' + t.question + '\nStudent: ' + t.student_answer + '\nModel: ' + t.model_answer;
      }).join('\n\n');
      var report  = await gradeVivaSession(tText);
      var vivaId  = savedVivaRef.current ? savedVivaRef.current.viva_id : null;
      if (vivaId) {
        await apiPost('/viva/' + vivaId + '/result', {
          total_score: report.total_score, grade: report.grade,
          full_transcript: tText, ai_report: report,
        });
      }
      setResults(report);
      setPhase('results');
    } catch (e) { alert(e.message); }
    setLoading(false);
  }

  // ── Send invites ───────────────────────────────────────────
  async function loadStudents() {
    try { var s = await apiGet('/students'); setStudents(s || []); } catch (e) {}
  }
  function toggleStudent(id) {
    setSelectedStu(function (prev) {
      return prev.includes(id) ? prev.filter(function (x) { return x !== id; }) : prev.concat([id]);
    });
  }
  async function sendInvites() {
    var vivaId = savedVivaRef.current ? savedVivaRef.current.viva_id : null;
    if (!vivaId) { alert('Room not created yet'); return; }
    setInviting(true); setInviteMsg('');
    var notifOk = 0;
    try {
      if (inviteMode === 'account' && selectedStu.length > 0) {
        for (var i = 0; i < selectedStu.length; i++) {
          var stu = students.find(function (s) { return s.user_id === selectedStu[i]; });
          if (stu) {
            await apiPost('/notifications', {
              title:       'Viva Invitation — ' + title,
              message:     'You have been invited to join the viva session "' + title + '". Topic: ' + (topic||'TBD') + '. Click "Join Now" in the Viva tab.',
              type:        'info',
              recipient_id: stu.user_id,
              viva_room_id: vivaId,
            });
            notifOk++;
          }
        }
        setInviteMsg('Sent invitations to ' + notifOk + ' student(s).');
        setSelectedStu([]);
      } else if (inviteMode === 'email' && inviteEmail.trim()) {
        var emails = inviteEmail.split(',').map(function (e) { return e.trim(); });
        await apiPost('/viva/invite', { emails: emails, title: title, topic: topic, vivaId: vivaId });
        setInviteMsg('Email invitations sent!');
        setInviteEmail('');
      }
    } catch (e) { setInviteMsg('Error: ' + e.message); }
    setInviting(false);
  }

  function copyRoomId() {
    var id = savedVivaRef.current ? savedVivaRef.current.viva_id : '';
    navigator.clipboard.writeText(id).then(function () { alert('Room ID copied!'); });
  }

  useEffect(function () { return function () { stopMedia(); }; }, []); // eslint-disable-line

  // ════════════════════════════════════════════════════════════
  // SETUP PHASE
  // ════════════════════════════════════════════════════════════
  if (phase === 'setup') {
    return (
      <div className="viva-dark fade-up">
        <div style={{ maxWidth:500, margin:'60px auto', textAlign:'center' }}>
          <div style={{ fontSize:'3rem', marginBottom:16 }}>🎙</div>
          <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:'1.6rem', color:'#fff', marginBottom:24 }}>Start Viva Room</div>
          <div className="card" style={{ textAlign:'left' }}>
            <div className="form-group"><label className="form-label">Session Title *</label><input className="form-input" value={title} onChange={function (e) { setTitle(e.target.value); }} placeholder="e.g. Data Structures Viva"/></div>
            <div className="form-group"><label className="form-label">Topic</label><input className="form-input" value={topic} onChange={function (e) { setTopic(e.target.value); }} placeholder="e.g. Trees and Graphs"/></div>
            <button className="btn btn-primary btn-lg" style={{ width:'100%', justifyContent:'center' }} onClick={handleStartRoom} disabled={loading||!title.trim()}>
              {loading ? 'Creating…' : '🚀 Start Viva Room'}
            </button>
          </div>
        </div>
      </div>
    );
  }

  // ════════════════════════════════════════════════════════════
  // RESULTS PHASE
  // ════════════════════════════════════════════════════════════
  if (phase === 'results' && results) {
    var gc = results.grade==='A'||results.grade==='A+'?'#16a34a':results.grade==='F'?'#dc2626':results.grade==='B'?'#2563eb':'#d97706';
    return (
      <div className="viva-dark fade-up">
        <div style={{ maxWidth:640, margin:'40px auto' }}>
          <div style={{ textAlign:'center', marginBottom:28 }}>
            <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:'1.5rem', color:'#fff', marginBottom:4 }}>📊 Viva Session Results</div>
            <div style={{ color:'#9ca3af' }}>{title}</div>
          </div>
          <div className="card" style={{ padding:28, marginBottom:20, textAlign:'center' }}>
            <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:900, fontSize:'4rem', color:gc, lineHeight:1 }}>{results.total_score}%</div>
            <div style={{ fontFamily:'Space Grotesk,sans-serif', fontWeight:800, fontSize:'1.8rem', color:gc, marginTop:4 }}>Grade {results.grade}</div>
            <div style={{ display:'flex', gap:32, justifyContent:'center', marginTop:16 }}>
              <div><div style={{ fontWeight:700, fontSize:'1.3rem', color:'#16a34a' }}>{results.correct_count||0}</div><div style={{ fontSize:'0.75rem', color:'#9ca3af' }}>Correct</div></div>
              <div><div style={{ fontWeight:700, fontSize:'1.3rem', color:'#dc2626' }}>{results.incorrect_count||0}</div><div style={{ fontSize:'0.75rem', color:'#9ca3af' }}>Incorrect</div></div>
              <div><div style={{ fontWeight:700, fontSize:'1.3rem', color:'#a78bfa' }}>{transcript.length}</div><div style={{ fontSize:'0.75rem', color:'#9ca3af' }}>Questions</div></div>
            </div>
          </div>
          {results.overall_feedback && (
            <div className="card" style={{ padding:'14px 18px', marginBottom:16 }}>
              <div style={{ fontSize:'0.72rem', fontWeight:700, color:'#9ca3af', letterSpacing:1, marginBottom:8, fontFamily:'JetBrains Mono,monospace' }}>OVERALL FEEDBACK</div>
              <div style={{ fontSize:'0.9rem', lineHeight:1.7 }}>{results.overall_feedback}</div>
            </div>
          )}
          <div className="card" style={{ padding:16, marginBottom:16 }}>
            <div style={{ fontSize:'0.72rem', fontWeight:700, color:'#9ca3af', letterSpacing:1, marginBottom:12, fontFamily:'JetBrains Mono,monospace' }}>QUESTION BREAKDOWN</div>
            {(results.answers||[]).map(function (a, i) {
              var col = a.correct ? '#16a34a' : '#dc2626';
              return (
                <div key={i} style={{ padding:'10px 0', borderBottom:'1px solid rgba(255,255,255,.07)' }}>
                  <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', gap:10 }}>
                    <div style={{ fontWeight:600, fontSize:'0.88rem', flex:1 }}>Q{i+1}: {a.question}</div>
                    <span style={{ fontWeight:800, color:col, flexShrink:0 }}>{a.score||0}%</span>
                  </div>
                  <div style={{ fontSize:'0.8rem', color:'#9ca3af', marginTop:4 }}>{a.feedback}</div>
                  <span className={'badge badge-'+(a.correct?'success':'danger')} style={{ marginTop:6, fontSize:'0.65rem' }}>{a.verdict}</span>
                </div>
              );
            })}
          </div>
          <div style={{ display:'flex', gap:12 }}>
            <button className="btn btn-outline" style={{ flex:1, justifyContent:'center' }} onClick={function () { setPhase('setup'); setResults(null); setTranscript([]); setQuestions([]); setSavedViva(null); savedVivaRef.current=null; setTitle(''); setTopic(''); }}>🔄 New Session</button>
            <button className="btn btn-primary" style={{ flex:1, justifyContent:'center' }} onClick={function () { navigator.clipboard.writeText(JSON.stringify(results,null,2)); alert('Results copied to clipboard!'); }}>📋 Copy Report</button>
          </div>
        </div>
      </div>
    );
  }

  // ════════════════════════════════════════════════════════════
  // ROOM PHASE
  // ════════════════════════════════════════════════════════════
  var vivaId = savedVivaRef.current ? savedVivaRef.current.viva_id : '';

  return (
    <div className="viva-dark fade-up">

      {/* ── Top bar ── */}
      <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:14, flexWrap:'wrap', gap:10 }}>
        <div style={{ display:'flex', gap:10, alignItems:'center', flexWrap:'wrap' }}>
          <span className="badge badge-danger">🔴 LIVE VIVA</span>
          <span style={{ fontWeight:700, color:'#fff' }}>{title}</span>
          {topic && <span className="badge badge-primary" style={{ fontSize:'0.68rem' }}>{topic}</span>}
        </div>
        <div style={{ display:'flex', gap:8, flexWrap:'wrap' }}>
          {/* Room ID */}
          <button className="btn btn-sm" style={{ background:'rgba(255,255,255,.08)', color:'#e5e5e5', fontFamily:'JetBrains Mono,monospace', fontSize:'0.72rem' }} onClick={copyRoomId}>
            🔑 {vivaId.slice(0,8)}…
          </button>
          {/* Student alerts bell */}
          <button className="btn btn-sm" style={{ background: unreadAlerts>0?'rgba(220,38,38,.2)':'rgba(255,255,255,.08)', color: unreadAlerts>0?'#f87171':'#e5e5e5', position:'relative' }}
            onClick={function () { setShowAlerts(!showAlerts); setUnreadAlerts(0); }}>
            🔔 Alerts {unreadAlerts>0 && <span style={{ position:'absolute', top:-4, right:-4, width:16, height:16, borderRadius:'50%', background:'#dc2626', color:'#fff', fontSize:'0.65rem', display:'flex', alignItems:'center', justifyContent:'center', fontWeight:700 }}>{unreadAlerts}</span>}
          </button>
          {/* Invite */}
          <button className="btn btn-sm btn-outline" onClick={function () { setShowInvite(!showInvite); if (!showInvite) loadStudents(); }}>✉ Invite</button>
          {/* End */}
          <button className="btn btn-danger btn-sm" onClick={handleEndGrade} disabled={loading}>⏹ End &amp; Grade</button>
        </div>
      </div>

      {/* ── Student alerts panel ── */}
      {showAlerts && (
        <div className="card" style={{ marginBottom:14, maxHeight:260, overflowY:'auto' }}>
          <div style={{ fontSize:'0.72rem', fontWeight:700, color:'#9ca3af', letterSpacing:1, marginBottom:10, fontFamily:'JetBrains Mono,monospace' }}>STUDENT ACTIVITY ALERTS</div>
          {studentAlerts.length === 0
            ? <div style={{ fontSize:'0.85rem', color:'#6b7280', textAlign:'center', padding:'12px 0' }}>No alerts yet — polling every 6 s…</div>
            : studentAlerts.map(function (a, i) {
              var col = a.type==='urgent'?'#dc2626':a.type==='success'?'#16a34a':'#d97706';
              return (
                <div key={i} style={{ padding:'8px 10px', borderBottom:'1px solid rgba(255,255,255,.07)', borderLeft:'3px solid '+col, marginBottom:4 }}>
                  <div style={{ fontWeight:700, fontSize:'0.82rem', color:col }}>{a.title}</div>
                  <div style={{ fontSize:'0.78rem', color:'#9ca3af', marginTop:2 }}>{a.message}</div>
                </div>
              );
            })
          }
        </div>
      )}

      {/* ── Invite panel ── */}
      {showInvite && (
        <div className="card" style={{ marginBottom:14 }}>
          <div style={{ display:'flex', gap:8, marginBottom:12 }}>
            {['account','email'].map(function (m) {
              return <button key={m} onClick={function () { setInviteMode(m); }} className={'btn btn-sm '+(inviteMode===m?'btn-primary':'btn-outline')} style={{ textTransform:'capitalize' }}>{m==='account'?'By Account':'By Email'}</button>;
            })}
          </div>
          {inviteMode === 'account' ? (
            <div>
              <div style={{ fontSize:'0.8rem', color:'#9ca3af', marginBottom:8 }}>Select students to invite:</div>
              <div style={{ maxHeight:160, overflowY:'auto', display:'flex', flexWrap:'wrap', gap:7 }}>
                {students.map(function (s) {
                  var sel = selectedStu.includes(s.user_id);
                  return (
                    <div key={s.user_id} onClick={function () { toggleStudent(s.user_id); }}
                      style={{ padding:'5px 12px', borderRadius:20, border:'1.5px solid '+(sel?'var(--accent)':'rgba(255,255,255,.15)'), background:sel?'rgba(124,58,237,.2)':'transparent', color:sel?'#a78bfa':'#9ca3af', fontSize:'0.8rem', fontWeight:sel?700:400, cursor:'pointer' }}>
                      {s.name}
                    </div>
                  );
                })}
              </div>
              {selectedStu.length > 0 && (
                <button className="btn btn-primary btn-sm" style={{ marginTop:10 }} onClick={sendInvites} disabled={inviting}>
                  {inviting ? 'Sending…' : 'Send to ' + selectedStu.length + ' Student(s)'}
                </button>
              )}
            </div>
          ) : (
            <div style={{ display:'flex', gap:8 }}>
              <input className="form-input" value={inviteEmail} onChange={function (e) { setInviteEmail(e.target.value); }} placeholder="student@email.com, another@email.com" style={{ flex:1 }}/>
              <button className="btn btn-primary btn-sm" onClick={sendInvites} disabled={inviting||!inviteEmail.trim()}>{inviting?'Sending…':'Send'}</button>
            </div>
          )}
          {inviteMsg && <div style={{ marginTop:8, fontSize:'0.8rem', color: inviteMsg.startsWith('Error')?'#f87171':'#4ade80' }}>{inviteMsg}</div>}
        </div>
      )}

      {/* ── 3-column layout ── */}
      <div className="viva-3col">

        {/* Left: camera + generate */}
        <div style={{ display:'flex', flexDirection:'column', gap:12, overflow:'auto' }}>
          <div className="card" style={{ padding:10 }}>
            <video ref={adminVid} autoPlay muted playsInline style={{ width:'100%', borderRadius:8, background:'#000', minHeight:140 }}/>
            <div style={{ fontSize:'0.72rem', textAlign:'center', marginTop:5, color:'#9ca3af' }}>Your Camera</div>
          </div>
          <div className="card" style={{ padding:12 }}>
            <div style={{ fontSize:'0.72rem', fontWeight:700, color:'#9ca3af', letterSpacing:1, marginBottom:10, fontFamily:'JetBrains Mono,monospace' }}>GENERATE QUESTIONS</div>
            <input className="form-input" value={genTopic} onChange={function (e) { setGenTopic(e.target.value); }} placeholder="Topic…" style={{ marginBottom:7 }}/>
            <div style={{ display:'flex', gap:7, marginBottom:7 }}>
              {[3,5,7,10].map(function (n) {
                return <button key={n} onClick={function () { setGenCount(n); }} style={{ flex:1, padding:'5px 0', borderRadius:6, border:'1px solid '+(genCount===n?'var(--accent)':'rgba(255,255,255,.15)'), background:genCount===n?'rgba(124,58,237,.25)':'transparent', color:genCount===n?'#a78bfa':'#9ca3af', fontSize:'0.8rem', fontWeight:700, cursor:'pointer' }}>{n}</button>;
              })}
            </div>
            <button className="btn btn-primary btn-sm" style={{ width:'100%' }} onClick={handleGenerateQ} disabled={loading||!genTopic.trim()}>{loading?'Generating…':'⚡ Generate'}</button>
          </div>
        </div>

        {/* Middle: current question + answer */}
        <div style={{ display:'flex', flexDirection:'column', gap:12, overflow:'auto' }}>
          {questions.length > 0 && questions[currentQ] ? (
            <div className="card">
              <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:10 }}>
                <span className="badge badge-primary">Q{currentQ+1} / {questions.length}</span>
                <span style={{ fontSize:'0.72rem', color:'#9ca3af' }}>{transcript.length} saved</span>
              </div>
              <div style={{ fontWeight:700, fontSize:'1rem', marginBottom:12, color:'#e5e5e5', lineHeight:1.55 }}>{questions[currentQ].question}</div>
              <div style={{ padding:'10px 12px', background:'rgba(124,58,237,.1)', borderRadius:8, fontSize:'0.82rem', color:'#a78bfa', marginBottom:14 }}>
                <div style={{ fontSize:'0.65rem', fontWeight:700, letterSpacing:1, marginBottom:5, fontFamily:'JetBrains Mono,monospace' }}>MODEL ANSWER (Examiner Only)</div>
                {questions[currentQ].model_answer}
              </div>
              <div className="form-group"><label className="form-label">Student's Answer</label>
                <textarea className="form-textarea" value={studentAnswer} onChange={function (e) { setStudentAnswer(e.target.value); }} rows={3} placeholder="Type what student said…"/>
              </div>
              <div className="form-group"><label className="form-label">Examiner Notes (optional)</label>
                <textarea className="form-textarea" value={examinerNotes} onChange={function (e) { setExaminerNotes(e.target.value); }} rows={2}/>
              </div>
              {verdict && (
                <div style={{ padding:12, background: verdict.correct?'rgba(22,163,74,.12)':'rgba(220,38,38,.12)', borderRadius:8, marginBottom:12, border:'1px solid '+(verdict.correct?'rgba(22,163,74,.3)':'rgba(220,38,38,.3)') }}>
                  <div style={{ display:'flex', justifyContent:'space-between', marginBottom:5 }}>
                    <span style={{ fontWeight:700, color: verdict.correct?'#4ade80':'#f87171' }}>{verdict.verdict}</span>
                    <span style={{ fontWeight:800, color:'#a78bfa' }}>{verdict.score_pct}%</span>
                  </div>
                  <div style={{ fontSize:'0.82rem', color:'#d1d5db' }}>{verdict.feedback}</div>
                  {verdict.missing && verdict.missing!=='None' && (
                    <div style={{ marginTop:6, fontSize:'0.78rem', color:'#fbbf24' }}>Missing: {verdict.missing}</div>
                  )}
                </div>
              )}
              <div style={{ display:'flex', gap:8 }}>
                <button className="btn btn-warning btn-sm" onClick={handleCheckAnswer} disabled={loading||!studentAnswer.trim()}>⚡ Grade</button>
                <button className="btn btn-success btn-sm" onClick={handleSaveNext} disabled={!verdict}>💾 Save &amp; Next</button>
              </div>
            </div>
          ) : (
            <div className="card" style={{ display:'flex', alignItems:'center', justifyContent:'center', minHeight:200 }}>
              <div style={{ textAlign:'center', color:'#9ca3af' }}>
                <div style={{ fontSize:'2.5rem', marginBottom:10 }}>🎤</div>
                <div style={{ fontWeight:600 }}>Generate questions to begin</div>
              </div>
            </div>
          )}
        </div>

        {/* Right: question list + transcript */}
        <div style={{ display:'flex', flexDirection:'column', gap:12, overflow:'auto' }}>
          <div className="card" style={{ padding:12 }}>
            <div style={{ fontSize:'0.72rem', fontWeight:700, color:'#9ca3af', letterSpacing:1, marginBottom:10, fontFamily:'JetBrains Mono,monospace' }}>QUESTIONS ({questions.length})</div>
            {questions.length === 0
              ? <div style={{ fontSize:'0.8rem', color:'#4b5563', textAlign:'center', padding:'10px 0' }}>None yet</div>
              : questions.map(function (q, i) {
                var done  = i < transcript.length;
                var isCur = i === currentQ;
                return (
                  <div key={i} onClick={function () { setCurrentQ(i); }}
                    style={{ padding:'7px 8px', borderRadius:6, cursor:'pointer', marginBottom:3, background: isCur?'rgba(124,58,237,.18)':'transparent', fontSize:'0.78rem', color: done?'#4ade80': isCur?'#e5e5e5':'#9ca3af', borderLeft: isCur?'3px solid var(--accent)':'3px solid transparent' }}>
                    {done?'✓ ':'  '}{i+1}. {q.question.slice(0,44)}{q.question.length>44?'…':''}
                  </div>
                );
              })
            }
          </div>
          <div className="card" style={{ padding:12, flex:1, overflow:'auto' }}>
            <div style={{ fontSize:'0.72rem', fontWeight:700, color:'#9ca3af', letterSpacing:1, marginBottom:10, fontFamily:'JetBrains Mono,monospace' }}>TRANSCRIPT ({transcript.length})</div>
            {transcript.length === 0
              ? <div style={{ fontSize:'0.8rem', color:'#4b5563', textAlign:'center', padding:'10px 0' }}>No entries yet</div>
              : transcript.map(function (t, i) {
                var v = t.verdict;
                var col = v ? (v.correct?'#4ade80':'#f87171') : '#9ca3af';
                return (
                  <div key={i} style={{ padding:'8px 0', borderBottom:'1px solid rgba(255,255,255,.06)' }}>
                    <div style={{ display:'flex', justifyContent:'space-between' }}>
                      <span style={{ fontWeight:600, fontSize:'0.78rem', color:'#e5e5e5' }}>Q{i+1}</span>
                      {v && <span style={{ fontWeight:800, fontSize:'0.78rem', color:col }}>{v.score_pct}%</span>}
                    </div>
                    <div style={{ fontSize:'0.75rem', color:'#9ca3af', marginTop:2 }}>A: {(t.student_answer||'').slice(0,55)}{(t.student_answer||'').length>55?'…':''}</div>
                  </div>
                );
              })
            }
          </div>
        </div>
      </div>
    </div>
  );
}
